CREATE OR REPLACE VIEW Fix_VFixed AS
SELECT
      F.Id , F.Num  , F.Perc , F.Name   , F.Rem  ,
      F.Num||' - '||F.Name     FName    ,
      S1.Id  Spc1_Id, S1.Name  Spc1_Name, S2.Id    Spc2_Id  , S2.Name  Spc2_Name,
      S3.Id  Spc3_Id, S3.Name  Spc3_Name, S4.Id    Spc4_Id  , S4.Name  Spc4_Name,
      S5.Id  Spc5_Id, S5.Name  Spc5_Name, U.Id     Unit_Id  , U.Name   Unit_Name,
      AA.Id  Acc_Id , AA.Num   Acc_Num  , AA.Name  Acc_Name , AA.Num||' - '||AA.Name  Acc_FullName,
      DA.Id  Acc_DId, DA.Num   Acc_DNum , DA.Name  Acc_DName, DA.Num||' - '||DA.Name  Acc_DFName  ,
      RA.Id  Acc_RId, RA.Num   Acc_RNum , RA.Name  Acc_RName, RA.Num||' - '||RA.Name  Acc_RFName  ,
      FA.Id  Acc_FId, FA.Num   Acc_FNum , FA.Name  Acc_FName, FA.Num||' - '||FA.Name  Acc_FFName
  From Fix_Fixed     F ,
       Fix_Cod_Spec1 S1,
       Fix_Cod_Spec2 S2,
       Fix_Cod_Spec3 S3,
       Fix_Cod_Spec4 S4,
       Fix_Cod_Spec5 S5,
       Cpy_Cod_Unit  U ,
       Acc_Acc       AA,
       Acc_Acc       DA,
       Acc_Acc       RA,
       Acc_Acc       FA
 Where F.Spc1_Id=S1.Id
   And F.Spc2_Id=S2.Id
   And F.Spc3_Id=S3.Id
   And F.Spc4_Id=S4.Id
   And F.Spc5_Id=S5.Id
   And F.Unit_Id=U.Id
   And IFNULL(F.Acc_Id ,0)=AA.Id
   And IFNULL(F.Acc_DId,0)=DA.Id
   And IFNULL(F.Acc_RId,0)=RA.Id
   And IFNULL(F.Acc_FId,0)=FA.Id;

