       Trn_Id      ,
       Trn_Id        Trn_IId       , Trn_SDate       Trn_ISDate       , Trn_EDate     Trn_IEDate    ,
       Trn_Qnt       Trn_IQnt      , Trn_CQnt        Trn_ICQnt        , Trn_SQnt      Trn_ISQnt     ,
       Trn_SCQnt     Trn_ISCQnt    , Trn_Price       Trn_IPrice       , Trn_Amt       Trn_IAmt      , Trn_CAmt        Trn_ICAmt        ,
