       Fixd_Spc5_Id, Fixd_Spc5_Name, Fixd_Unit_Id  , Fixd_Unit_Name   , Fixd_Acc_Id , Fixd_Acc_Num  , Fixd_Acc_Name , Fixd_Acc_FullName,
       Fixd_Acc_DId, Fixd_Acc_DNum , Fixd_Acc_DName, Fixd_Acc_DFName  , Fixd_Acc_RId, Fixd_Acc_RNum , Fixd_Acc_RName, Fixd_Acc_RFName  ,
