       Loc3_Id     , Loc3_Name     , Status_Id     , Status_Name      , Spc1_Id     , Spc1_Name     , Spc2_Id       , Spc2_Name        ,
       Spc3_Id     , Spc3_Name     , Spc4_Id       , Spc4_Name        ,
       Spc5_Id     , Spc5_Name
  From Fix_VInDocs
UNION ALL
SELECT
       200           Type_Id       , 'إخراج'         Type_Name        ,
       Mst_Id      , Mst_Num       , Mst_Date      , Mst_Rem          , Vhr_Id    ,
       Period_Id   , Period_Name   , Commit_Id     , Commit_Name      ,
       Acc_Id      , Acc_Num       , Acc_Name      , Acc_FName        ,
       Trn_Id      ,
       Trn_IId     , Trn_ISDate    , Trn_IEDate    ,
       Trn_IQnt    , Trn_ICQnt     , Trn_ISQnt     ,
       Trn_ISCQnt  , Trn_IPrice    , Trn_IAmt      , Trn_ICAmt        ,
       Trn_IPerc   , Trn_IFTot     , Trn_IFAmt     , Trn_IRTot        ,
       Trn_IRAmt   , Trn_IRem      , Trn_ISpc6     ,
       Trn_Rem     ,
       Trn_Qnt     , Trn_UCst      , Trn_Cst       , Trn_Price        , Trn_Amt     , Trn_Perc      , Trn_FTot      , Trn_FAmt         ,
