       Fixd_Spc1_Id, Fixd_Spc1_Name, Fixd_Spc2_Id  , Fixd_Spc2_Name   , Fixd_Spc3_Id, Fixd_Spc3_Name, Fixd_Spc4_Id  , Fixd_Spc4_Name   ,
       Fixd_Spc5_Id, Fixd_Spc5_Name, Fixd_Unit_Id  , Fixd_Unit_Name   , Fixd_Acc_Id , Fixd_Acc_Num  , Fixd_Acc_Name , Fixd_Acc_FullName,
       Fixd_Acc_DId, Fixd_Acc_DNum , Fixd_Acc_DName, Fixd_Acc_DFName  , Fixd_Acc_RId, Fixd_Acc_RNum , Fixd_Acc_RName, Fixd_Acc_RFName  ,
       Fixd_Acc_FId, Fixd_Acc_FNum , Fixd_Acc_FName, Fixd_Acc_FFName  , Loc1_Id     , Loc1_Name     , Loc2_Id       , Loc2_Name        ,
       Loc3_Id     , Loc3_Name     , Status_Id     , Status_Name      , Spc1_Id     , Spc1_Name     , Spc2_Id       , Spc2_Name        ,
       Spc3_Id     , Spc3_Name     , Spc4_Id       , Spc4_Name        ,
       Spc5_Id     , Spc5_Name
  From Fix_VOuDocs;
